```python
    @classmethod
    def _parse_diagnostic_ledger_envelope(cls, raw, keys, format_value, versions, what):
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError(f"{what} is not valid UTF-8: {exc}") from exc
        if text.startswith("\ufeff"):
            raise ValueError(f"{what} must be UTF-8 without a BOM")
        if text.endswith("\n") or text.endswith("\r"):
            raise ValueError(f"{what} must not have a trailing newline")
        try:
            document = json.loads(text, object_pairs_hook=cls._reject_duplicate_json_keys)
        except ValueError as exc:
            raise ValueError(f"{what} is not valid JSON: {exc}") from exc
        if cls._canonical_json(document) != text:
            raise ValueError(f"{what} is not canonical compact JSON")
        if not isinstance(document, dict) or set(document) != set(keys):
            raise ValueError(f"{what} has bad top-level keys")
        if document["format"] != format_value:
            raise ValueError(f"{what} has an unknown format")
        version = document["version"]
        if isinstance(version, bool) or not isinstance(version, int) or version not in versions:
            raise ValueError(f"{what} has an unsupported version")
        checksum = document["checksum"]
        if not isinstance(checksum, str) or len(checksum) != 64 or set(checksum) - cls._HEX_DIGITS:
            raise ValueError(f"{what} checksum is malformed")
        body = {k: v for k, v in document.items() if k != "checksum"}
        if not hmac.compare_digest(checksum, sha256(canonical(body))):
            raise ValueError(f"{what} checksum does not verify")
        return document
